BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),email text NOT NULL,username text NOT NULL,password_hash text,password_changed_at timestamptz,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,email),UNIQUE(organization_id,username));
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations(id),name text NOT NULL,scope text NOT NULL CHECK(scope IN('ORGANIZATION','PROGRAM','PROJECT')),system_role boolean NOT NULL DEFAULT false,UNIQUE(organization_id,name));
CREATE TABLE permissions(code text PRIMARY KEY,description text NOT NULL);
CREATE TABLE role_permissions(role_id uuid REFERENCES roles(id) ON DELETE CASCADE,permission_code text REFERENCES permissions(code) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_code));
CREATE TABLE programs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),program_id uuid REFERENCES programs(id),project_key text NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,project_key));
CREATE TABLE user_role_scopes(user_id uuid REFERENCES users(id) ON DELETE CASCADE,role_id uuid REFERENCES roles(id) ON DELETE CASCADE,organization_id uuid REFERENCES organizations(id),program_id uuid REFERENCES programs(id),project_id uuid REFERENCES projects(id),PRIMARY KEY(user_id,role_id,organization_id,program_id,project_id));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,csrf_hash text NOT NULL,ip inet,user_agent text,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE password_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),email text NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,status text NOT NULL DEFAULT 'PLANNED',target_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sprints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,start_date date,end_date date,status text NOT NULL DEFAULT 'PLANNED');
CREATE TABLE object_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),project_id uuid REFERENCES projects(id),object_key text NOT NULL UNIQUE,original_name text NOT NULL,mime_type text,size_bytes bigint NOT NULL,sha256 char(64) NOT NULL,scan_status text NOT NULL DEFAULT 'PENDING',extraction_status text NOT NULL DEFAULT 'PENDING',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),requirement_key text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',current_version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,requirement_key));
CREATE TABLE requirement_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_id uuid NOT NULL REFERENCES requirements(id),version integer NOT NULL,normalized_text text NOT NULL,source_type text NOT NULL,generation_method text NOT NULL DEFAULT 'HUMAN',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),approved_by uuid REFERENCES users(id),approved_at timestamptz,UNIQUE(requirement_id,version));
CREATE TABLE requirement_files(requirement_version_id uuid REFERENCES requirement_versions(id) ON DELETE CASCADE,file_id uuid REFERENCES object_files(id),PRIMARY KEY(requirement_version_id,file_id));
CREATE TABLE requirement_analysis(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_version_id uuid NOT NULL UNIQUE REFERENCES requirement_versions(id),actors jsonb NOT NULL DEFAULT '[]',business_rules jsonb NOT NULL DEFAULT '[]',acceptance_criteria jsonb NOT NULL DEFAULT '[]',risks jsonb NOT NULL DEFAULT '[]',test_types jsonb NOT NULL DEFAULT '[]',source_evidence jsonb NOT NULL DEFAULT '[]',analyzer_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scenarios(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),requirement_version_id uuid NOT NULL REFERENCES requirement_versions(id),title text NOT NULL,category text NOT NULL,priority text NOT NULL,source_evidence jsonb NOT NULL DEFAULT '[]',generation_method text NOT NULL,approval_status text NOT NULL DEFAULT 'DRAFT',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scenario_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scenario_id uuid NOT NULL REFERENCES scenarios(id) ON DELETE CASCADE,step_order integer NOT NULL,action text NOT NULL,expected text,UNIQUE(scenario_id,step_order));
CREATE TABLE test_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),scenario_id uuid REFERENCES scenarios(id),case_key text NOT NULL,title text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',current_version integer NOT NULL DEFAULT 1,UNIQUE(project_id,case_key));
CREATE TABLE test_case_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),test_case_id uuid NOT NULL REFERENCES test_cases(id),version integer NOT NULL,requirement_version_id uuid NOT NULL REFERENCES requirement_versions(id),preconditions text,test_type text NOT NULL,priority text NOT NULL,automation_scope text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(test_case_id,version));
CREATE TABLE test_case_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),test_case_version_id uuid NOT NULL REFERENCES test_case_versions(id) ON DELETE CASCADE,step_order integer NOT NULL,action text NOT NULL,expected text NOT NULL,test_data jsonb,UNIQUE(test_case_version_id,step_order));
CREATE TABLE test_suites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,status text NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE suite_cases(suite_id uuid REFERENCES test_suites(id) ON DELETE CASCADE,test_case_id uuid REFERENCES test_cases(id),sort_order integer NOT NULL,PRIMARY KEY(suite_id,test_case_id));
CREATE TABLE environments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,base_url text,health text NOT NULL DEFAULT 'UNKNOWN',secret_reference text,variables jsonb NOT NULL DEFAULT '{}');
CREATE TABLE automation_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),test_case_id uuid REFERENCES test_cases(id),asset_type text NOT NULL,engine text NOT NULL,status text NOT NULL DEFAULT 'DRAFT',current_version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE automation_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),automation_asset_id uuid NOT NULL REFERENCES automation_assets(id),version integer NOT NULL,definition jsonb NOT NULL,approved_at timestamptz,UNIQUE(automation_asset_id,version));
CREATE TABLE workers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),worker_key text NOT NULL UNIQUE,worker_type text NOT NULL,os text,engine_version text,capabilities jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'OFFLINE',last_heartbeat_at timestamptz,current_execution_id uuid,token_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),release_id uuid REFERENCES releases(id),environment_id uuid NOT NULL REFERENCES environments(id),execution_type text NOT NULL,status text NOT NULL CHECK(status IN('READY','QUEUED','RUNNING','PASSED','FAILED','SKIPPED','BLOCKED','CANCELLED')),mode text NOT NULL,worker_count integer NOT NULL DEFAULT 1,retry_policy jsonb NOT NULL DEFAULT '{}',requested_by uuid NOT NULL REFERENCES users(id),queued_at timestamptz,started_at timestamptz,ended_at timestamptz,correlation_id uuid NOT NULL DEFAULT gen_random_uuid());
ALTER TABLE workers ADD CONSTRAINT workers_execution_fk FOREIGN KEY(current_execution_id) REFERENCES executions(id);
CREATE TABLE execution_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid NOT NULL REFERENCES executions(id) ON DELETE CASCADE,test_case_version_id uuid NOT NULL REFERENCES test_case_versions(id),worker_id uuid REFERENCES workers(id),status text NOT NULL DEFAULT 'QUEUED',attempt integer NOT NULL DEFAULT 1,started_at timestamptz,ended_at timestamptz,failure_classification text,error_message text);
CREATE TABLE execution_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_case_id uuid NOT NULL REFERENCES execution_cases(id) ON DELETE CASCADE,step_order integer NOT NULL,status text NOT NULL,started_at timestamptz,ended_at timestamptz,actual text,error_message text);
CREATE TABLE execution_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_case_id uuid NOT NULL REFERENCES execution_cases(id) ON DELETE CASCADE,file_id uuid NOT NULL REFERENCES object_files(id),evidence_type text NOT NULL,retention_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE defects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),requirement_version_id uuid REFERENCES requirement_versions(id),test_case_id uuid REFERENCES test_cases(id),execution_case_id uuid REFERENCES execution_cases(id),title text NOT NULL,severity text NOT NULL,priority text NOT NULL,status text NOT NULL DEFAULT 'NEW',owner_id uuid REFERENCES users(id),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE defect_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),defect_id uuid NOT NULL REFERENCES defects(id) ON DELETE CASCADE,author_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),sprint_id uuid REFERENCES sprints(id),assignee_id uuid REFERENCES users(id),title text NOT NULL,stlc_stage text,status text NOT NULL,planned_hours numeric(8,2),actual_hours numeric(8,2) DEFAULT 0,blocker text);
CREATE TABLE leave_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),project_id uuid REFERENCES projects(id),user_id uuid NOT NULL REFERENCES users(id),leave_type text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,hours numeric(8,2) NOT NULL,status text NOT NULL DEFAULT 'PENDING',approved_by uuid REFERENCES users(id));
CREATE TABLE resource_skills(user_id uuid REFERENCES users(id),skill text NOT NULL,proficiency text NOT NULL,evidence text,PRIMARY KEY(user_id,skill));
CREATE TABLE training(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,status text NOT NULL,due_date date);
CREATE TABLE performance_improvement_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),manager_id uuid NOT NULL REFERENCES users(id),objectives jsonb NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE performance_tests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),engine text NOT NULL,configuration jsonb NOT NULL,status text NOT NULL DEFAULT 'DRAFT');
CREATE TABLE performance_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),performance_test_id uuid NOT NULL REFERENCES performance_tests(id),execution_id uuid REFERENCES executions(id),metrics jsonb NOT NULL,threshold_result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE security_tests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),scanner_type text NOT NULL,configuration jsonb NOT NULL,status text NOT NULL DEFAULT 'DRAFT');
CREATE TABLE security_findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),security_test_id uuid NOT NULL REFERENCES security_tests(id),fingerprint text NOT NULL,severity text NOT NULL,cwe text,owasp text,title text NOT NULL,evidence jsonb NOT NULL,status text NOT NULL DEFAULT 'OPEN',UNIQUE(security_test_id,fingerprint));
CREATE TABLE mobile_tests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),engine text NOT NULL,device_matrix jsonb NOT NULL,configuration jsonb NOT NULL,status text NOT NULL DEFAULT 'DRAFT');
CREATE TABLE report_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),project_id uuid REFERENCES projects(id),report_type text NOT NULL,period_start timestamptz,period_end timestamptz,timezone text NOT NULL,status text NOT NULL,file_id uuid REFERENCES object_files(id),requested_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid,project_id uuid,actor_id uuid,ip inet,user_agent text,occurred_at timestamptz NOT NULL DEFAULT now(),action text NOT NULL,entity_type text NOT NULL,entity_id text,request_id uuid NOT NULL,correlation_id uuid,before_data jsonb,after_data jsonb,result text NOT NULL,previous_hash char(64),event_hash char(64) NOT NULL);
CREATE OR REPLACE FUNCTION prevent_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'audit_events is append-only';END$$;
CREATE TRIGGER audit_events_no_update BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_change();
CREATE INDEX idx_projects_org ON projects(organization_id);CREATE INDEX idx_req_project ON requirements(project_id);CREATE INDEX idx_scenario_req ON scenarios(requirement_version_id);CREATE INDEX idx_cases_project ON test_cases(project_id);CREATE INDEX idx_exec_project_status ON executions(project_id,status);CREATE INDEX idx_audit_org_time ON audit_events(organization_id,occurred_at DESC);CREATE INDEX idx_session_hash ON sessions(token_hash) WHERE revoked_at IS NULL;
INSERT INTO permissions(code,description) VALUES
('organizations.manage','Manage organization'),('programs.manage','Manage programs'),('projects.read','Read project'),('projects.manage','Manage project'),('requirements.read','Read requirements'),('requirements.create','Create requirements'),('requirements.update','Update requirements'),('requirements.approve','Approve requirements'),('scenarios.read','Read scenarios'),('scenarios.create','Create scenarios'),('cases.read','Read cases'),('cases.create','Create cases'),('cases.approve','Approve cases'),('executions.read','Read executions'),('executions.run','Run executions'),('executions.cancel','Cancel executions'),('defects.read','Read defects'),('defects.create','Create defects'),('defects.assign','Assign defects'),('defects.transition','Transition defects'),('reports.view','View reports'),('reports.export','Export reports'),('users.manage','Manage users'),('roles.manage','Manage roles'),('audit.view','View audit'),('backup.create','Create backup'),('backup.restore','Restore backup'),('workers.manage','Manage workers');
INSERT INTO schema_migrations(version) VALUES('001_enterprise_core');
COMMIT;
